import java.util.Arrays;
public class Main {
    static class CircularQueue {
        int[] data = new int[3]; int front, size;
        void add(int value) { data[(front + size) % data.length] = value; size++; }
        int remove() { int value = data[front]; front = (front + 1) % data.length; size--; return value; }
        public String toString() { int[] out = new int[size]; for (int i = 0; i < size; i++) out[i] = data[(front + i) % data.length]; return Arrays.toString(out); }
    }
    public static void main(String[] args) {
        CircularQueue queue = new CircularQueue(); queue.add(1); queue.add(2); queue.remove(); queue.add(3);
        System.out.println(queue + " " + queue.size);
    }
}
